16	// ComponentForm est un formulaire pour ajouter/éditer un composant
17	type ComponentForm struct {
18		// Inputs
19		nameInput    textinput.Model
20		targetInput  textinput.Model
21		timeoutInput textinput.Model
22		countInput   textinput.Model // Pour ICMP
23		nsInput      textinput.Model // Pour DNS nameserver
24	
25		// État
26		focusIndex int
27		compType   string // http, https, icmp, dns
28		editing    bool   // true si édition, false si création
29		original   *config.ComponentConfig
30	
31		// Dimensions
32		width  int
33		height int
34	}
35	
36	// NewComponentForm crée un nouveau formulaire de composant
37	func NewComponentForm(component *config.ComponentConfig) *ComponentForm {
38		nameInput := textinput.New()
39		nameInput.Placeholder = "my-service"
40		nameInput.CharLimit = 50
41		nameInput.Width = 40
42		nameInput.Focus()
43	
44		targetInput := textinput.New()
45		targetInput.Placeholder = "example.com or 192.168.1.1"
46		targetInput.CharLimit = 200
47		targetInput.Width = 40
48	
49		timeoutInput := textinput.New()
50		timeoutInput.Placeholder = "10"
51		timeoutInput.CharLimit = 3
52		timeoutInput.Width = 10
53	
54		countInput := textinput.New()
55		countInput.Placeholder = "4"
56		countInput.CharLimit = 2
57		countInput.Width = 10
58	
59		nsInput := textinput.New()
60		nsInput.Placeholder = "8.8.8.8 (optional)"
61		nsInput.CharLimit = 50
62		nsInput.Width = 40
63	
64		// Apply theme background to all textinputs
65		theme.StyleTextInput(&nameInput)
66		theme.StyleTextInput(&targetInput)
67		theme.StyleTextInput(&timeoutInput)
68		theme.StyleTextInput(&countInput)
69		theme.StyleTextInput(&nsInput)
70	
71		form := &ComponentForm{
72			nameInput:    nameInput,
73			targetInput:  targetInput,
74			timeoutInput: timeoutInput,
75			countInput:   countInput,
76			nsInput:      nsInput,
77			focusIndex:   0,
78			compType:     "https",
79			editing:      component != nil,
80		}
81	
82		// Si édition, pré-remplir les champs
83		if component != nil {
84			form.original = component
85			form.nameInput.SetValue(component.Name)
86			form.targetInput.SetValue(component.Target)
87			if component.Timeout > 0 {
88				form.timeoutInput.SetValue(fmt.Sprintf("%d", component.Timeout))
89			}
90			if component.Count > 0 {
91				form.countInput.SetValue(fmt.Sprintf("%d", component.Count))
92			}
93			if component.Nameserver != "" {
94				form.nsInput.SetValue(component.Nameserver)
95			}
96			if component.Type != "" {
97				form.compType = component.Type
98			}
99		}
100	
101		return form
102	}
103	
104	// ComponentFormSubmitMsg est envoyé quand le formulaire est soumis
105	type ComponentFormSubmitMsg struct {
106		Component config.ComponentConfig
107		Original  *config.ComponentConfig // Non nil si édition
108	}
109	
110	// ComponentFormCancelledMsg est envoyé quand le formulaire est annulé
111	type ComponentFormCancelledMsg struct{}
112	
113	// Update met à jour le formulaire
114	func (f *ComponentForm) Update(msg tea.Msg) (*ComponentForm, tea.Cmd) {
115		switch msg := msg.(type) {
116		case tea.WindowSizeMsg:
117			f.width = msg.Width
118			f.height = msg.Height
119		case tea.KeyMsg:
120			return f.handleKeyMsg(msg)
121		}
122	
123		return f, f.updateActiveInput(msg)
124	}
125	
126	// handleKeyMsg traite les entrées clavier du formulaire
127	func (f *ComponentForm) handleKeyMsg(msg tea.KeyMsg) (*ComponentForm, tea.Cmd) {
128		switch msg.String() {
129		case "esc":
130			return nil, nil
131		case "down":
132			f.navigateField(1)
133			return f, nil
134		case "up":
135			f.navigateField(-1)
136			return f, nil
137		case "left":
138			if f.focusIndex == 3 {
139				f.cycleType(-1)
140				return f, nil
141			}
142		case "right":
143			if f.focusIndex == 3 {
144				f.cycleType(1)
145				return f, nil
146			}
147		case "enter":
148			return f.handleEnterKey()
149		}
150		return f, f.updateActiveInput(msg)
151	}
152	
153	// maxFieldIndex returns the maximum field index based on component type
154	func (f *ComponentForm) maxFieldIndex() int {
155		if f.compType == "http" || f.compType == "https" || f.compType == "ssl" {
156			return 4
157		}
158		return 5
159	}
160	
161	// navigateField moves focus by delta (+1 or -1) with wrapping
162	func (f *ComponentForm) navigateField(delta int) {
163		maxIndex := f.maxFieldIndex()
164		f.focusIndex += delta
165		if f.focusIndex > maxIndex {
166			f.focusIndex = 0
167		}
168		if f.focusIndex < 0 {
169			f.focusIndex = maxIndex
170		}
171		f.updateFocus()
172	}
173	
174	// handleEnterKey traite la touche Enter (submit ou avance au champ suivant)
175	func (f *ComponentForm) handleEnterKey() (*ComponentForm, tea.Cmd) {
176		if f.focusIndex == f.maxFieldIndex() {
177			return f.submitForm()
178		}
179		return f, nil
180	}
181	
182	// submitForm valide et soumet le formulaire
183	func (f *ComponentForm) submitForm() (*ComponentForm, tea.Cmd) {
184		name := strings.TrimSpace(f.nameInput.Value())
185		target := strings.TrimSpace(f.targetInput.Value())
186		if name == "" || target == "" {
187			return f, nil
188		}
189	
190		component := config.ComponentConfig{
191			Name:    name,
192			Type:    f.compType,
193			Target:  target,
194			Timeout: f.parseTimeout(),
195		}
196	
197		if f.compType == "icmp" {
198			component.Count = f.parseCount()
199		}
200		if f.compType == "dns" {
201			component.Nameserver = strings.TrimSpace(f.nsInput.Value())
202		}
203	
204		return f, func() tea.Msg {
205			return ComponentFormSubmitMsg{
206				Component: component,
207				Original:  f.original,
208			}
209		}
210	}
211	
212	// parseTimeout parses the timeout input value with default of 10
213	func (f *ComponentForm) parseTimeout() int {
214		if t := strings.TrimSpace(f.timeoutInput.Value()); t != "" {
215			if parsed, err := strconv.Atoi(t); err == nil {
216				return parsed
217			}
218		}
219		return 10
220	}
221	
222	// parseCount parses the ping count input value with default of 4
223	func (f *ComponentForm) parseCount() int {
224		if c := strings.TrimSpace(f.countInput.Value()); c != "" {
225			if parsed, err := strconv.Atoi(c); err == nil {
226				return parsed
227			}
228		}
229		return 4
230	}
231	
232	// updateActiveInput met à jour l'input qui a le focus
233	func (f *ComponentForm) updateActiveInput(msg tea.Msg) tea.Cmd {
234		var cmd tea.Cmd
235		switch f.focusIndex {
236		case 0:
237			f.nameInput, cmd = f.nameInput.Update(msg)
238		case 1:
239			f.targetInput, cmd = f.targetInput.Update(msg)
240		case 2:
241			f.timeoutInput, cmd = f.timeoutInput.Update(msg)
242		case 4:
243			switch f.compType {
244			case "icmp":
245				f.countInput, cmd = f.countInput.Update(msg)
246			case "dns":
247				f.nsInput, cmd = f.nsInput.Update(msg)
248			}
249		}
250		return cmd
251	}
252	
253	// updateFocus met à jour le focus des inputs
254	func (f *ComponentForm) updateFocus() {
255		f.nameInput.Blur()
256		f.targetInput.Blur()
257		f.timeoutInput.Blur()
258		f.countInput.Blur()
259		f.nsInput.Blur()
260	
261		switch f.focusIndex {
262		case 0:
263			f.nameInput.Focus()
264		case 1:
265			f.targetInput.Focus()
266		case 2:
267			f.timeoutInput.Focus()
268		case 4:
269			switch f.compType {
270			case "icmp":
271				f.countInput.Focus()
272			case "dns":
273				f.nsInput.Focus()
274			}
275		}
276	}
277	
278	// cycleType change le type de composant dans la direction donnée (+1 ou -1)
279	func (f *ComponentForm) cycleType(dir int) {
280		types := []string{"http", "https", "icmp", "dns", "ssl"}
281		n := len(types)
282		for i, t := range types {
283			if t == f.compType {
284				f.compType = types[(i+dir+n)%n]
285				f.updatePlaceholders()
286				return
287			}
288		}
289	}
290	
291	// updatePlaceholders updates placeholder text based on selected type
292	func (f *ComponentForm) updatePlaceholders() {
293		switch f.compType {
294		case "ssl":
295			f.targetInput.Placeholder = "example.com:443 or example.com"
296		case "http":
297			f.targetInput.Placeholder = "example.com or 192.168.1.1"
298		case "https":
299			f.targetInput.Placeholder = "example.com or 192.168.1.1"
300		case "icmp":
301			f.targetInput.Placeholder = "192.168.1.1 or hostname"
302		case "dns":
303			f.targetInput.Placeholder = "example.com"
304		}
305	}
306	
307	// GetTitle returns the form title for use in the viewport breadcrumb
308	func (f *ComponentForm) GetTitle() string {
309		if f.editing {
310			return "Edit Monitor"
311		}
312		return "Add New Monitor"
313	}
314	
315	// View affiche le formulaire
316	func (f *ComponentForm) View() string {
317		var b strings.Builder
318	
319		b.WriteString(theme.EmptyLineBg(f.width) + "\n")
320	
321		// Champ Name
