333			b.WriteString(theme.Bg("  Target "+theme.IconChevronRight) + "\n")
334		}
335		b.WriteString(theme.Bg("  ") + f.targetInput.View() + "\n\n")
336	
337		// Champ Timeout
338		if f.focusIndex == 2 {
339			b.WriteString(theme.KeyStyle.Render(theme.IconCircleSmall+" Timeout (seconds) "+theme.IconChevronRight) + "\n")
340		} else {
341			b.WriteString(theme.Bg("  Timeout (seconds) "+theme.IconChevronRight) + "\n")
