	form := m.GetShortcuts()
	if hasShortcut(form, "ctrl+n") {
		t.Error("the form state still offers ctrl+n, which does nothing there")
	}
	if !hasShortcut(form, "esc") || !hasShortcut(form, "enter") {
		t.Error("the form state does not offer cancel and submit")
	}
