66	func TestCheckCompleteStoresResultsAndSchedulesTheNext(t *testing.T) {
67		m := newTestModel(t, monitorConfigs()...)
68		m.checking = true
69		timestamp := time.Date(2026, 8, 2, 12, 0, 0, 0, time.UTC)
70	
71		m = feed(t, m, CheckCompleteMsg{Components: checkResults(), Timestamp: timestamp})
72	
73		if m.checking {
74			t.Error("checking = true after the results arrived")
75		}
76		if m.firstCheck {
77			t.Error("firstCheck = true after the first results arrived")
78		}
79		if !m.lastCheck.Equal(timestamp) {
80			t.Errorf("lastCheck = %v, want %v", m.lastCheck, timestamp)
81		}
82		if want := timestamp.Add(m.refreshInterval); !m.nextCheck.Equal(want) {
83			t.Errorf("nextCheck = %v, want %v (lastCheck + interval)", m.nextCheck, want)
84		}
85		if len(m.components) != len(checkResults()) {
86			t.Errorf("stored %d components, want %d", len(m.components), len(checkResults()))
87		}
88		if m.error != "" {
89			t.Errorf("error = %q after a successful check", m.error)
90		}
