132			{"due and idle", false, false, time.Now().Add(-time.Second), true},
133			{"not due yet", false, false, time.Now().Add(time.Hour), false},
134			{"paused", true, false, time.Now().Add(-time.Second), false},
135			{"already checking", false, true, time.Now().Add(-time.Second), true},
136		}
137	
138		for _, tc := range tests {
139			t.Run(tc.name, func(t *testing.T) {
140				m := loadedModel(t)
141				m.paused = tc.paused
142				m.checking = tc.checking
143				m.nextCheck = tc.nextCheck
144	
145				m, cmd := step(t, m, TickMsg(time.Now()))
146	
147				if m.checking != tc.wantChecking {
148					t.Errorf("checking = %v, want %v", m.checking, tc.wantChecking)
149				}
150				if cmd == nil {
